import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { UserService } from '../../services/user.service';
import { Component, Inject, PLATFORM_ID, OnInit } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
@Component({
  selector: 'app-after-login',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './after-login.html',
  styleUrls: ['./after-login.css']
})
export class AfterLogin implements OnInit {
  private router = inject(Router);
  private userService = inject(UserService);

  showBalance = true;
  userData: any = null;
  balance = '24.500,00'; // Valor padrão, pode ser carregado da API

  ngOnInit() {
    // Carregar dados do usuário se estiver no localStorage
    const userEmail = localStorage.getItem('userEmail');
    const storedUserData = localStorage.getItem('userData');
    
    if (storedUserData) {
      try {
        this.userData = JSON.parse(storedUserData);
      } catch (e) {
        console.error('Erro ao parsear dados do usuário:', e);
      }
    }

    // Se tiver email, pode buscar dados atualizados da API
    if (userEmail) {
      this.loadUserData(userEmail);
    }
  }

  loadUserData(email: string) {
    this.userService.fetch<any>(email).subscribe({
      next: (data) => {
        this.userData = data;
        localStorage.setItem('userData', JSON.stringify(data));
      },
      error: (error) => {
        console.error('Erro ao carregar dados do usuário:', error);
      }
    });
  }

  toggleBalance() {
    this.showBalance = !this.showBalance;
  }

  goToPix() {
    this.router.navigate(['/nav/Pix']);
  }
}
